"""Print the code point ranges expat accepts as XML name (start) characters.

Used to derive the name tables in engine/src/wfhtml/tables.rs. Run from the
repository root with
`uv run python -I engine/tests/fixtures/wfhtml/probe_names.py > engine/src/wfhtml/name_tables.rs`.
Expat (in UTF-8 mode, as Python's pyexpat uses it for str input) uses the XML 1.0
4th-edition name tables, not the 5th-edition ranges, so they are probed rather than
written down from the specification.
"""

import sys
import xml.parsers.expat


def ok(doc: str) -> bool:
    p = xml.parsers.expat.ParserCreate()
    try:
        p.Parse(doc, True)
    except (xml.parsers.expat.ExpatError, ValueError):
        return False
    return True


def ranges(pred):
    out = []
    start = None
    for cp in range(0x110000):
        v = False if 0xD800 <= cp <= 0xDFFF else pred(chr(cp))
        if v and start is None:
            start = cp
        elif not v and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out


def rust(name, rs):
    print(f"pub(super) const {name}: &[(u32, u32)] = &[")
    for a, b in rs:
        print(f"    (0x{a:04X}, 0x{b:04X}),")
    print("];")


print(f"// @generated by engine/tests/fixtures/wfhtml/probe_names.py from Python {sys.version.split()[0]}")
print(f"// pyexpat ({xml.parsers.expat.EXPAT_VERSION}). Do not edit by hand.")
print("//")
print("// Inclusive code point ranges that expat accepts as the first character of an XML")
print("// name (NAME_START) and as a later character (NAME_CHAR): the XML 1.0 4th-edition")
print("// tables. No character outside the BMP is a name character for expat.")
print()
rust("NAME_START", ranges(lambda c: ok(f"<_wfroot><{c}/></_wfroot>")))
rust("NAME_CHAR", ranges(lambda c: ok(f"<_wfroot><a{c}a/></_wfroot>")))
